  mutate(CRE = case_when(str_detect(CRE, "<0.2\\*") ~ 0.1, TRUE ~ as.numeric(CRE)),
         ALP = case_when(str_detect(ALP, "<5\\*") ~ 2.5, TRUE ~ as.numeric(ALP)),
