### Summary Stats

## function to selectively round based on value
smart_round <- function(x) {
  ifelse(abs(x) >= 1,
         # numbers ≥ 1 to 1 decimal place
         round(x, 1),   
         ## numbers < 1 to 2 decimal places
         round(x, 2)) }

blood_summary <- blood %>%
  select(Virus, Day, where(is.numeric)) %>%  ## keep Virus, Day + numeric columns
  pivot_longer(-c(Virus, Day), names_to = "variable", values_to = "value") %>%
  group_by(Virus, Day, variable) %>%
  reframe(
    N = sum(!is.na(value)),
    min = min(value, na.rm = TRUE),
    max = max(value, na.rm = TRUE),
    med = median(value, na.rm = TRUE),
    mean = mean(value, na.rm = TRUE),
    sd = sd(value, na.rm = TRUE),
    se = sd / sqrt(N),
    CI.l.mean = mean - qt(0.975, df = N - 1) * sd / sqrt(N),
    CI.u.mean = mean + qt(0.975, df = N - 1) * sd / sqrt(N)) %>%
  ## round all numbers except N to 1 digit
  mutate(across(where(is.numeric) & !c(N), smart_round)) %>%
  filter(N > 0) %>%
  ## paste together variables with parentheses for consolidated table
  mutate(mean_range = paste0(mean, " (", min, "-", max, ")")) #%>%
  ## consistent decimals
  #mutate(summary = sprintf("%.2f (%.2f-%.2f)", mean_val, min_val, max_val))

#write.csv(blood_summary, file = 'blood_summary_stats_rounded.csv')

set.seed(123)
baseline_summary <- blood %>%
  filter(Day %in% c(-4, 0)) %>%
  select(Day, where(is.numeric)) %>%  ## keep Day + numeric columns
  pivot_longer(WBC:GLOB, names_to = "variable", values_to = "value") %>%
  group_by(variable) %>%
  reframe(
    N = sum(!is.na(value)),
    min = min(value, na.rm = TRUE),
    max = max(value, na.rm = TRUE),
    med = median(value, na.rm = TRUE),
    mean = mean(value, na.rm = TRUE),
    sd = sd(value, na.rm = TRUE),
    se = sd / sqrt(N),
    CI.l.mean = mean - qt(0.975, df = N - 1) * sd / sqrt(N),
    CI.u.mean = mean + qt(0.975, df = N - 1) * sd / sqrt(N),
    ## raw percentiles
    RI  = list(quantile(value, probs = c(0.025, 0.975), na.rm = TRUE)),
    RI2 = list(quantile(value, probs = c(0.05, 0.95), na.rm = TRUE)),
    ## bootstrap percentiles
    boot_RI = list({
      n_boot <- 5000
      boot_samples <- replicate(n_boot, sample(value, replace = TRUE))
      boot_percentiles <- apply(boot_samples, 2, function(x) 
        quantile(x, probs = c(0.025, 0.975), na.rm = TRUE))
      rowMeans(boot_percentiles)}),
    boot_RI2 = list({
      n_boot <- 5000
      boot_samples <- replicate(n_boot, sample(value, replace = TRUE))
      boot_percentiles <- apply(boot_samples, 2, function(x) 
        quantile(x, probs = c(0.05, 0.95), na.rm = TRUE))
      rowMeans(boot_percentiles)}),
    
    ## quantiles
    Q1 = quantile(value, 0.25, na.rm = TRUE),
    Q3 = quantile(value, 0.75, na.rm = TRUE),
    IQR = Q3 - Q1,
    ## Tukey's fences - outlier detection
    lower_fence = Q1 - 1.5 * IQR,   ## 1.5 mild outliers, 3 for extreme outliers
    upper_fence = Q3 + 1.5 * IQR,
    #outlier_iqr = value < lower_fence | value > upper_fence,
    ## MAD (median absolute deviation) - outlier detection
    mad_val = mad(value, constant = 1, na.rm = TRUE), ## 1 for raw MAD, 1.4826 for scaled = SD like
    #outlier_mad = abs(value - med) > 3 * mad_val, ## 3 strict, 2.5 for moderate
    
    ### measures of data variability:
    ## Gini coefficient - measure of variability, 0-1
    gini = DescTools::Gini(value, na.rm = TRUE),
    ## Coefficient of Variation (CV)
    cv = (sd / mean) * 100,
    ## Robust CV based on IQR (RCV𝑄)
    rcvq = (0.75 * (IQR/med)) * 100,
    ## Robust CV based on MAD (RCV𝑀)
    rcvm = (1.4826 * (mad_val/med)) * 100) %>%
  unnest_wider(RI, names_sep = "_") %>%
  unnest_wider(RI2, names_sep = "_") %>%
  unnest_wider(boot_RI, names_sep = "_boot") %>%
  unnest_wider(boot_RI2, names_sep = "_boot") %>%
  ungroup()

baseline_summary <- baseline_summary %>%
  ## round all numbers except N to 1 digit
  mutate(across(where(is.numeric) & !c(N), smart_round)) %>%
  ## paste together variables with parentheses for consolidated table
  mutate(mean_range = paste0(mean, " (", min, "-", max, ")"),
         lower_fence = abs(lower_fence),
         #lower_fence = ifelse(lower_fence < 0, 0, lower_fence),
         Tukey_range = paste0(mean, " (", lower_fence, "-", upper_fence, ")"))

