## color shading ferrets to match 'virus_colors', with black bars below LOD/euth

## function to make n shades around a base color
make_shades <- function(base, n) {
  if (n <= 1) return(rep(base, n))
  ramp <- grDevices::colorRampPalette(
    c(lighten(base, 0.4), base, darken(base, 0.4)))
  ramp(n) }

## one color per ID, shaded by its Virus' base color
id_key <- NW_titers %>%
  distinct(Virus, ID) %>%
  arrange(Virus, ID) %>%
  group_split(Virus) %>%
  map_dfr(function(d) {
    base <- virus_colors[as.character(d$Virus[1])]
    d$shade <- make_shades(base, nrow(d))
    d }) %>%
  ## colors for each Virus-ID combo
  mutate(VID = interaction(Virus, ID, drop = TRUE))

## colors for each ferret ID
id_colors <- setNames(id_key$shade, id_key$ID)
## color for euth ferret bars below LOD
pal <- c(id_colors, "below" = "black")

## summarize to the means
