## baseline data
baseline <- data %>%
  filter(Day %in% c(-4, 0)) %>%
  pivot_longer(all_of(lab_cols), names_to = "variable", values_to = "value") %>%
  group_by(ID, variable) %>%
  reframe(mean_baseline = mean(value, na.rm = TRUE))

## combine 
data_long <- data %>%
  pivot_longer(all_of(lab_cols), names_to = "variable", values_to = "value") %>%
  left_join(baseline, by = c("ID", "variable")) %>%
  mutate(delta    = value - mean_baseline,
         ratio    = value / mean_baseline,
         logratio = log(ratio)) ## for skewed chemistry

## check data for Inf & NaN values
sapply(data_long, function(x) any(is.infinite(x)))
sapply(data_long, function(x) any(is.nan(x)))
## found in 'ratio' columns

## set Inf & NaN values to NA
data_long[sapply(data_long, is.infinite)] <- NA
data_long[sapply(data_long, is.nan)] <- NA

