### Baseline Range

baseline_ranges <- blood %>%
  filter(Day %in% c(-4, 0)) %>%
  select(Day, where(is.numeric)) %>%
  pivot_longer(WBC:GLOB, names_to = "variable", values_to = "value") %>%
  group_by(variable) %>%
  summarise(RI = list(quantile(value, probs = c(0.025, 0.975), na.rm = TRUE))) %>%
  tidyr::unnest_wider(RI, names_sep = "_")

###

## create a ribbon dataframe that spans the full Day range for each variable
ribbon_df <- data_long %>%
  filter(!str_detect(variable, "_p")) %>%
  filter(Day > 0) %>%
  distinct(variable, Day) %>%
  left_join(baseline_ranges) %>%
  rename(RI_low = `RI_2.5%`, RI_high = `RI_97.5%`)

