### Are variables different from baseline? (within‑animal inference)

## using z-scores to detect outside (above/below) reference interval baselines

baseline_tbl <- read.csv(file = 'R_inputs/baseline_tbl.csv', header = TRUE)

dfb <- data %>% 
  select(-c(Group1:Group2, Date, Weekday, notes, Notes, 
            Blood_Collection:Yellow_Sera, Weight, Temp,
            wt_loss_cum_p, contains('euth'), contains('change'))) %>% 
  rename('NA_' = 'NA') %>%
  mutate(Day = ifelse(Day == -4, 0, Day)) %>%
  drop_na(WBC)

subject_col <- "ID"
group_cols <- c("Virus", "Treatment", "Day")

## compute z, p, and outside flag for all numeric variables present in baseline_tbl
vars <- baseline_tbl$variable
## function
compute_metrics <- function(df, baseline_tbl, vars) {
  df_long <- df %>%
    select(all_of(c(subject_col, group_cols, vars))) %>%
    pivot_longer(cols = all_of(vars), names_to = "variable", values_to = "value")
  
  df_long2 <- df_long %>%
    left_join(baseline_tbl, by = "variable") %>%
    mutate(z = (value - mean) / sd,
           p_two_sided = 2 * (1 - pnorm(abs(z))), 
           outside_RI = ifelse(is.na(value), NA, (value < RI_2.5) | (value > RI_97.5)))
  return(df_long2) }

## run function on data
dfb_long <- compute_metrics(dfb, baseline_tbl, vars)

## quick summary: counts of outside by variable, Virus, and Day
summary_flags <- dfb_long %>%
  filter(Day %in% c(1, 2, 4, 6, 10)) %>% ## filter added 25 June 2026
  group_by(variable, Day, Virus) %>%
  summarize(n = sum(!is.na(outside_RI)),
            n_outside = sum(outside_RI, na.rm = TRUE),
            prop_outside = n_outside / n,
            outside_RI = ifelse(prop_outside > 0, TRUE, FALSE),
            mean_z = mean(z, na.rm = TRUE),
            abs_mean_z = abs(mean_z),
            median_z = median(z, na.rm = TRUE),
            abs_median_z = abs(median_z),
            ## proportion with |z| > x
            prop_gtRI = mean(abs(z) > 1.96, na.rm = TRUE), ## 95% RI
            prop_gt2 = mean(abs(z) > 2, na.rm = TRUE), ## ~4.6%  of values from a standard normal exceed 2
            prop_gt3 = mean(abs(z) > 3, na.rm = TRUE)) %>%
  ungroup()
## z score of 4.15 is ~4.15 baseline SDs above the baseline mean
## positive means above baseline, negative means below baseline
View(summary_flags)

## summarize all infection days together - per Virus/variable only
summary_flags2 <- dfb_long %>%
  filter(Day > 0) %>%
  filter(Day %in% c(1, 2, 4, 6, 10)) %>% ## filter added 25 June 2026
  group_by(variable, Virus) %>%
  summarize(n = sum(!is.na(outside_RI)),
            n_outside = sum(outside_RI, na.rm = TRUE),
            prop_outside = n_outside / n,
            outside_RI = ifelse(prop_outside > 0, TRUE, FALSE),
            mean_z = mean(z, na.rm = TRUE),
            abs_mean_z = abs(mean_z),
            median_z = median(z, na.rm = TRUE),
            abs_median_z = abs(median_z),
            ## proportion with |z| > x
            prop_gtRI = mean(abs(z) > 1.96, na.rm = TRUE), ## 95% RI
            prop_gt2 = mean(abs(z) > 2, na.rm = TRUE), ## ~4.6%  of values from a standard normal exceed 2
            prop_gt3 = mean(abs(z) > 3, na.rm = TRUE)) %>%
  ungroup()
View(summary_flags2)

